from harvests import load_harvests, ROWS
from changes import kilos_changes, biggest_rise

VALUES = [v for _, v in ROWS]
EXPECTED = [VALUES[i] - VALUES[i - 1] for i in range(1, len(VALUES))]


def test_number_of_changes():
    assert len(kilos_changes(list(load_harvests()))) == len(ROWS) - 1


def test_values():
    assert kilos_changes(list(load_harvests())) == EXPECTED


def test_two_items():
    assert kilos_changes(list(load_harvests())[:2]) == EXPECTED[:1]


def test_biggest_rise():
    assert biggest_rise(list(load_harvests())) == max([c for c in EXPECTED if c > 0] or [0])


def test_single_item():
    assert kilos_changes(list(load_harvests())[:1]) == [] and kilos_changes([]) == []

