def kilos_changes(harvests):
    """Return the change in kilos from each harvest to the next: one entry for every neighbouring pair."""
    out = []
    for i in range(1, len(harvests)):
        out.append(harvests[i].kilos - harvests[i - 1].kilos)
    return out
